css:
.scp0:focus { transform: none !important; }
.scp1:hover { color: var(--text-strong) !important; }
.scp2:hover { background: var(--action-ghost-hover) !important; }
.scp3:hover { background: color-mix(in srgb, currentcolor 12%, transparent 88%) !important; }
.scp4:active { transform: scale(var(--press-scale)) !important; }
.scp5:hover { color: var(--on-ink-strong) !important; }
